@dataclass(frozen=True)
class WorkshopConfig:
    catalog: str = "hytech_ws_catalog"
    raw_schema: str = "raw"
    solutions_schema: str = "solutions"
    ops_schema: str = "ops"
    participant_group: str = "de_workshop_sz"
    llm_endpoint: str = "databricks-claude-sonnet-4-5"
    servers: tuple[str, ...] = DEFAULT_SERVERS
    seed: int = 42
    history_days: int = 90  # days of deals before the CDC window
    cdc_window_hours: int = 48  # hourly CDC files between the full load (T0) and "now"
    users_per_server: int = 1500
    positions_per_server_per_day: int = 1400
    event_days: int = 7
    events_per_day: int = 20_000
    volume_root: str | None = None  # override (local tests): replaces /Volumes/<catalog>/<raw_schema>

    @property
    def raw_root(self) -> str:
        return self.volume_root or f"/Volumes/{self.catalog}/{self.raw_schema}"

    @property
    def landing_root(self) -> str:
        return f"{self.raw_root}/landing"

    @property
    def ref_root(self) -> str:
        return f"{self.raw_root}/ref"

    @property
    def producer_root(self) -> str:
        return f"{self.raw_root}/producer"

    @property
    def events_dir(self) -> str:
        return f"{self.landing_root}/app_events"

    def mt5_dir(self, server: str, table: str) -> str:
        return f"{self.landing_root}/mt5/{server}/{table}"


def participant_schema(user_name: str) -> str:
    """每个参与者的 schema 名称，例如 ``zhihan.tan@databricks.com`` -> ``u_zhihan_tan``。
    Per-participant schema name, e.g. ``zhihan.tan@databricks.com`` -> ``u_zhihan_tan``."""
    local = user_name.split("@")[0].lower()
    cleaned = "".join(ch if ch.isalnum() else "_" for ch in local).strip("_")
    return f"u_{cleaned}"
